"use strict";
Gordic.Previews.register("fuc:Pripad", {
    // je možné náhled vykreslit?
    canRender: function (dto) {
        return dto.ixp_upr != null;
    },
    // vykreslení náhledu
    render: function (div, dto) {
        let currentElement = $(div);
        // titulek
        // TODO: dolatit podle detailu a šipek posunu po seznamu
        currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'>Případ " + (dto.ac_ag ?? dto.ixp_upr ?? "") + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/>");
        // link na otevření detailu v nové záložce
        Gordic.Previews.displayLinkButton(div, dto);
        // PID zvlášť (je přes celou šířku)
        // TODO: PID se nezobrazuje?
        let form = $.newDiv("gform--view-mode").appendTo(currentElement);
        form.gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" })
            .gformsection("create")
            .gpidbar({ pid: dto.ixp_upr });
        // a pak ostatní data
        let formBuilder = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1, breaks-300-400" })
            // TODO: členit to na (pojmenované?) sekce?
            .addSection()
            .addRow("Identifikátor").addField("gstaticfield", { name: "ixp_upr" /* Gordic.Fuc.Interface.GPripadDtoNames.ixp_upr */ })
            .addRow("Agenda").addField("gstaticfield", { name: "zkr_ag" /* Gordic.Fuc.Interface.GPripadDtoNames.zkr_ag */ })
            .addRow("Agendové číslo").addField("gstaticfield", { name: "ac_ag" /* Gordic.Fuc.Interface.GPripadDtoNames.ac_ag */ })
            .addRow("Evidenční číslo").addField("gstaticfield", { name: "ac" /* Gordic.Fuc.Interface.GPripadDtoNames.ac */ })
            .addRow("Datum evidence").addField("gstaticfield", { name: "dat_evid" /* Gordic.Fuc.Interface.GPripadDtoNames.dat_evid */, itemTemplate: "{#:date}" })
            .addSection()
            .addRow("Typ dokladu").addField("gstaticfield", { name: "ixs_typ_txt" /* Gordic.Fuc.Interface.GPripadDtoNames.ixs_typ_txt */ })
            .addRow("Kategorie případu").addField("gstaticfield", { name: "ktg_upr_txt" /* Gordic.Fuc.Interface.GPripadDtoNames.ktg_upr_txt */ })
            .addRow("Typ případu").addField("gstaticfield", { name: "typ_upr_txt" /* Gordic.Fuc.Interface.GPripadDtoNames.typ_upr_txt */ })
            .addSection()
            .addRow("Popis").addField("gstaticfield", { name: "popis" /* Gordic.Fuc.Interface.GPripadDtoNames.popis */ })
            .addRow("Poznámka").addField("gstaticfield", { name: "poznamka" /* Gordic.Fuc.Interface.GPripadDtoNames.poznamka */ })
            .addSection()
            .addRow("Subjekt").addField("gstaticfield", { name: "subjekt" /* Gordic.Fuc.Interface.GPripadDtoNames.subjekt */ + "." + "esu_txt" /* Gordic.Fuc.Interface.GExterniSubjektDtoNames.esu_txt */ })
            .addSection()
            .addRow("Částka v měně").addField("gstaticfield", { name: "c_mena" /* Gordic.Fuc.Interface.GPripadDtoNames.c_mena */, itemTemplate: Gordic.Fuc.WebClient.FucPreview.getCMenaItemTemplate(dto.mena_zkr) })
            .addRow("Částka v CZK").addField("gstaticfield", { name: "c_celk" /* Gordic.Fuc.Interface.GPripadDtoNames.c_celk */, itemTemplate: "{#:number(C2)} CZK" })
            .addSection()
            .addRow("Stav případu").addField("gstaticfield", { name: "s_upr_txt" /* Gordic.Fuc.Interface.GPripadDtoNames.s_upr_txt */ })
            .addRow("Stav zaúčtování").addField("gstaticfield", { name: "s_zau_txt" /* Gordic.Fuc.Interface.GPripadDtoNames.s_zau_txt */ })
            .addRow("Stav storna").addField("gstaticfield", { name: "s_sto_txt" /* Gordic.Fuc.Interface.GPripadDtoNames.s_sto_txt */ })
            .addSection()
            .addRow("Počet pohybů").addField("gstaticfield", { name: "pocet_pohybu" /* Gordic.Fuc.Interface.GPripadDtoNames.pocet_pohybu */ })
            .addRow("Počet plateb").addField("gstaticfield", { name: "pocet_plateb" /* Gordic.Fuc.Interface.GPripadDtoNames.pocet_plateb */ });
        // vytvoření formuláře a naplnění dat
        form.gform("createFrom", formBuilder).findFields().gfield("model", "apply", dto);
        currentElement.trigger("resize").find(".gform-section").children("label").first().addClass("g-state-text g-state-active");
    }
});
Gordic.Previews.register("fuc:Pohyb", {
    // je možné náhled vykreslit?
    canRender: function (dto) {
        return (dto.ixp_upr != null && dto.radek_upo != null);
    },
    // vykreslení náhledu
    render: function (div, dto) {
        let currentElement = $(div);
        // titulek
        // TODO: dolatit podle detailu a šipek posunu po seznamu
        currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'>Pohyb " + dto.radek_upo + " případu " + (dto.upr_ac_ag ?? dto.ixp_upr ?? "") + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/ > ");
        // PID zvlášť (je přes celou šířku)
        let form = $.newDiv("gform--view-mode").appendTo(currentElement);
        form.gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
            gformsection("create").gpidbar({ pid: dto.ixp_upr });
        // a pak ostatní data
        let formBuilder = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1, breaks-300-400" })
            .addRow("identifikátor").addField("gstaticfield", { name: "ixp_upr" /* Gordic.Fuc.Interface.GPohybDtoNames.ixp_upr */ })
            .addRow("Řádek").addField("gstaticfield", { name: "radek_upo" /* Gordic.Fuc.Interface.GPohybDtoNames.radek_upo */ })
            .addSection()
            .addRow("Druh pohybu").addField("gstaticfield", { name: "druh_poh_txt" /* Gordic.Fuc.Interface.GPohybDtoNames.druh_poh_txt */, })
            .addRow("Typ pohybu").addField("gstaticfield", { name: "typ_upo_txt" /* Gordic.Fuc.Interface.GPohybDtoNames.typ_upo_txt */ })
            // TODO: přidat info o daňovém/nedaňovém pohybu (to dát i na seznam pohybů)
            .addRow("Pohyb").addField("gstaticfield", { name: "priz_dd" /* Gordic.Fuc.Interface.GPohybDtoNames.priz_dd */, itemTemplate: function (o) { return (o > 0 ? "daňový" : "nedaňový"); } })
            .addRow("Typ případu").addField("gstaticfield", { name: "typ_upr_txt" /* Gordic.Fuc.Interface.GPohybDtoNames.typ_upr_txt */ })
            .addRow("Kategorie pohybu").addField("gstaticfield", { name: "ktg_upo_txt" /* Gordic.Fuc.Interface.GPohybDtoNames.ktg_upo_txt */ })
            .addSection()
            .addRow("Stav").addField("gstaticfield", { name: "s_upo_txt" /* Gordic.Fuc.Interface.GPohybDtoNames.s_upo_txt */ })
            .addRow("Stav storna").addField("gstaticfield", { name: "s_sto_txt" /* Gordic.Fuc.Interface.GPohybDtoNames.s_sto_txt */ })
            .addSection()
            .addRow("Datum pohybu").addField("gstaticfield", { name: "dat_upo" /* Gordic.Fuc.Interface.GPohybDtoNames.dat_upo */, itemTemplate: "{#:date}" })
            .addSection()
            .addRow("Popis").addField("gstaticfield", { name: "popis_upo" /* Gordic.Fuc.Interface.GPohybDtoNames.popis_upo */ })
            .addSection()
            .addRow("Subjekt").addField("gstaticfield", { name: "subjekt" /* Gordic.Fuc.Interface.GPohybDtoNames.subjekt */ + "." + "esu_txt" /* Gordic.Fuc.Interface.GExterniSubjektDtoNames.esu_txt */ })
            .addSection()
            .addRow("jres:24100082").addField("gstaticfield", { name: "c_mena" /* Gordic.Fuc.Interface.GPohybDtoNames.c_mena */, itemTemplate: Gordic.Fuc.WebClient.FucPreview.getCMenaItemTemplate(dto.mena_zkr) }) //RC 24100082 : Částka v měně
            .addRow("jres:24100083").addField("gstaticfield", { name: "c_upo" /* Gordic.Fuc.Interface.GPohybDtoNames.c_upo */, itemTemplate: "{#:number(C2)} CZK" }) //RC 24100083 : Částka v CZK
            .addSection()
            .addRow("Číslo dokladu").addField("gstaticfield", { name: "ac_ixe_txt", })
            .addRow("Datum účtování").addField("gstaticfield", { name: "dat_zauc" /* Gordic.Fuc.Interface.GPohybDtoNames.dat_zauc */ })
            .addRow("Období danění").addField("gstaticfield", { name: "obd_dan" /* Gordic.Fuc.Interface.GPohybDtoNames.obd_dan */ });
        // pomocné (složené) hodnoty pro náhled
        let druh_poh_txt = "";
        if (dto.druh_poh_txt)
            druh_poh_txt = dto.druh_poh_txt;
        else {
            switch (dto.druh_poh) {
                case 10:
                    druh_poh_txt = "účetní";
                    break;
                case 20:
                    druh_poh_txt = "rezervační";
                    break;
                case 30:
                    druh_poh_txt = "neúčetní";
                    break;
                default: druh_poh_txt = "neurčeno";
            }
        }
        let ac_ixe_txt = "";
        if (dto.ac_ixe != null && dto.ac_ixe > " ")
            ac_ixe_txt = dto.ac_ixe;
        else if (dto.subrada_duz != null && dto.subrada_duz > 0)
            ac_ixe_txt = "*" + dto.subrada_duz;
        // vytvoření formuláře a naplnění dat
        form.gform("createFrom", formBuilder).findFields().gfield("model", "apply", $.extend(true, dto, { druh_poh_txt: druh_poh_txt, ac_ixe_txt: ac_ixe_txt }));
        currentElement.trigger("resize").find(".gform-section").children("label").first().addClass("g-state-text g-state-active");
    }
});
